                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                            seen.add(p); stack.append(p)
                comps.append((color,comp))
    out=[[0]*w for _ in range(h)]
    for color,comp in comps:
        r0=min(r for r,c in comp); r1=max(r for r,c in comp)
        c0=min(c for r,c in comp); c1=max(c for r,c in comp)
        shape={(r-r0,c-c0) for r,c in comp}
        bh,bw=r1-r0+1,c1-c0+1
        # Objects enclosing at least one background cell rise to the top; others settle at the bottom.
        outside=set(); stack=[]
        for y in range(bh):
            for x in range(bw):
                if y in (0,bh-1) or x in (0,bw-1):
                    if (y,x) not in shape and (y,x) not in outside:
                        outside.add((y,x)); stack.append((y,x))
        while stack:
            y,x=stack.pop()
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(y+dy,x+dx)
                if 0<=p[0]<bh and 0<=p[1]<bw and p not in shape and p not in outside:
                    outside.add(p); stack.append(p)
        has_hole=any((y,x) not in shape and (y,x) not in outside for y in range(bh) for x in range(bw))
        nr0=0 if has_hole else h-bh
        for r,c in comp:
            out[nr0+r-r0][c]=color
    return out
