                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            y0 = min(y for y, x in cells)
            y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells)
            x1 = max(x for y, x in cells)
            shape = {(y - y0, x - x0) for y, x in cells}
            hh, ww = y1 - y0 + 1, x1 - x0 + 1
            outside, queue = set(), []
            for y in range(hh):
                for x in range(ww):
                    if (y in (0, hh - 1) or x in (0, ww - 1)) and (y, x) not in shape:
                        outside.add((y, x))
