            while queue:
                y, x = queue.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < hh and 0 <= p[1] < ww and p not in shape and p not in outside:
                        outside.add(p)
                        queue.append(p)
            hollow = any((y, x) not in shape and (y, x) not in outside for y in range(hh) for x in range(ww))
            objects.append({'color': color, 'cells': cells, 'y0': y0, 'y1': y1, 'hollow': hollow})

    # Hollow/enclosed figures rise; other figures fall. Resolve each stream from
    # the direction of travel so that nearer objects form the first obstacles.
    hollow = sorted((o for o in objects if o['hollow']), key=lambda o: o['y0'])
    solid = sorted((o for o in objects if not o['hollow']), key=lambda o: -o['y1'])
    result = [[0] * w for _ in range(h)]
    for obj in hollow + solid:
        cells = obj['cells']
        dy = -1 if obj['hollow'] else 1
